import hashlib,json,subprocess
from pathlib import Path
root=Path('/Users/baai/.codex/worktrees/native-compiler-routing-synthesis/FlagQuantum')
out=root/'docs/development/evidence'
writes={}
for draw in ('inspected','fresh'):
    path=Path('/private/tmp/fq-native-matrix-'+draw+'-20261123.json')
    raw=path.read_bytes(); report=json.loads(raw)
    assert report['completed'] and report['admission_passed'] and len(report['rows'])==120
    payloads=report['payloads'];report['payloads']={}
    chunks=[];chunk={}
    for key,value in payloads.items():
        if chunk and len(json.dumps({**chunk,key:value},separators=(',',':')).encode())>1100000:
            chunks.append(chunk);chunk={}
        chunk[key]=value
    if chunk: chunks.append(chunk)
    refs=[]
    for i,chunk in enumerate(chunks):
        name=f'native-preview-matrices-{draw}-payloads-{i:02d}.json'
        data=(json.dumps(chunk,separators=(',',':'),allow_nan=False)+'\n').encode()
        writes[name]=data;refs.append({'name':name,'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)})
    envelope={'original_report_sha256':hashlib.sha256(raw).hexdigest(),'original_report_bytes':len(raw),'payload_files':refs,'report':report,'archive_driver_source':Path(__file__).read_text()}
    restored={}
    for ref in refs: restored.update(json.loads(writes[ref['name']]))
    report['payloads']=restored
    assert (json.dumps(report,indent=2,allow_nan=False)+'\n').encode()==raw
    report['payloads']={}
    writes[f'native-preview-matrices-{draw}-screen.json']=(json.dumps(envelope,indent=2,allow_nan=False)+'\n').encode()
for category in ('replay','resources'):
    writes[f'native-preview-matrices-{category}.json']=Path('/private/tmp/fq-native-matrix-'+category+'-20261123.json').read_bytes()
paths=['docs/development/evidence/'+name for name in writes]
subprocess.run(['/Users/baai/Documents/liuwei/sdkbench/.venv/bin/python','tools/check_team_scope.py','--team','compiler','--files',*paths],cwd=root,check=True,timeout=20)
for name,data in writes.items():
    (out/name).write_bytes(data)
    print(name,len(data),hashlib.sha256(data).hexdigest())
